"""
Alert model — safety incidents generated from telemetry rule evaluation.
"""
import uuid
from datetime import datetime, timezone
from app.extensions import db

# alert_type values
ALERT_TYPES = (
    "overspeed", "geofence_entry", "geofence_exit",
    "truck_offline", "sos", "low_battery",
    "harsh_brake", "harsh_acceleration", "maintenance_due",
)


class Alert(db.Model):
    """Incident alert generated by fleet monitoring rules."""
    __tablename__ = "alerts"

    id = db.Column(db.String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    organization_id = db.Column(
        db.String(36),
        db.ForeignKey("organizations.id", ondelete="CASCADE"),
        nullable=True, index=True
    )
    vehicle_id = db.Column(
        db.String(36),
        db.ForeignKey("vehicles.id", ondelete="CASCADE"),
        nullable=False, index=True
    )
    geofence_id = db.Column(
        db.String(36),
        db.ForeignKey("geofences.id", ondelete="SET NULL"),
        nullable=True
    )
    trip_id = db.Column(
        db.String(36),
        db.ForeignKey("trips.id", ondelete="SET NULL"),
        nullable=True
    )
    # See ALERT_TYPES above
    alert_type = db.Column(db.String(30), nullable=False)
    # info | warning | critical
    severity = db.Column(db.String(15), default="warning", nullable=False)
    message = db.Column(db.String(255), nullable=False)
    latitude = db.Column(db.Float, nullable=True)
    longitude = db.Column(db.Float, nullable=True)
    speed_kmh = db.Column(db.Float, nullable=True)
    is_acknowledged = db.Column(db.Boolean, default=False, nullable=False)
    acknowledged_by = db.Column(
        db.String(36),
        db.ForeignKey("users.id", ondelete="SET NULL"),
        nullable=True
    )
    acknowledged_at = db.Column(db.DateTime(timezone=True), nullable=True)
    created_at = db.Column(db.DateTime(timezone=True),
                           default=lambda: datetime.now(timezone.utc),
                           nullable=False, index=True)

    def to_dict(self):
        return {
            "id": self.id,
            "organization_id": self.organization_id,
            "vehicle_id": self.vehicle_id,
            "registration_number": self.vehicle.registration_number if self.vehicle else None,
            "geofence_id": self.geofence_id,
            "geofence_name": self.geofence.name if self.geofence else None,
            "trip_id": self.trip_id,
            "alert_type": self.alert_type,
            "severity": self.severity,
            "message": self.message,
            "latitude": self.latitude,
            "longitude": self.longitude,
            "speed_kmh": self.speed_kmh,
            "is_acknowledged": self.is_acknowledged,
            "acknowledged_by": self.acknowledged_by,
            "acknowledged_at": (
                self.acknowledged_at.isoformat() if self.acknowledged_at else None
            ),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
